import React, { useState } from "react";

const UploadSection = ({ setResults }) => {
  const [file, setFile] = useState(null);
  const [model, setModel] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!file || !model) {
      alert("Please upload CSV and select a model.");
      return;
    }

    const formData = new FormData();
    formData.append("file", file);
    formData.append("model", model);
    formData.append("target_column", "Churn"); // default target

    try {
      const res = await fetch("http://127.0.0.1:8000/predict", {
        method: "POST",
        body: formData,
      });

      if (!res.ok) {
        const errorData = await res.json();
        alert("Error: " + errorData.detail);
        return;
      }

      const data = await res.json();
      console.log("Prediction Response:", data);

      setResults(data);
    } catch (error) {
      alert("Backend error: " + error);
      console.error(error);
    }
  };

  return (
    <div
      style={{
        background: "linear-gradient(135deg, #ff9a9e, #fad0c4)",
        padding: "30px",
        borderRadius: "15px",
        marginTop: "40px",
        boxShadow: "0 6px 20px rgba(0,0,0,0.3)",
      }}
    >
      <h2 style={{ marginBottom: "15px" }}>Upload Dataset & Choose Model</h2>

      {/* File Upload */}
      <input
        type="file"
        accept=".csv"
        onChange={(e) => setFile(e.target.files[0])}
        style={{
          padding: "10px",
          background: "white",
          borderRadius: "8px",
          marginBottom: "15px",
        }}
      />

      <br />

      {/* Dropdown */}
      <select
        onChange={(e) => setModel(e.target.value)}
        style={{
          padding: "10px",
          width: "230px",
          borderRadius: "8px",
          marginTop: "10px",
          marginBottom: "20px",
        }}
      >
        <option value="">Select Model</option>
        <option value="logistic_regression">Logistic Regression</option>
        <option value="naive_bayes">Naive Bayes</option>
        <option value="knn">KNN</option>
        <option value="svm">SVM</option>
        <option value="decision_tree">Decision Tree</option>
        <option value="random_forest">Random Forest</option>
        <option value="xgboost">XGBoost</option>
        <option value="lightgbm">LightGBM</option>
      </select>

      <br />

      {/* Predict Button */}
      <button
        className="predict-btn"
        onClick={(e) => {
          const rect = e.target.getBoundingClientRect();
          e.target.style.setProperty("--x", e.clientX - rect.left + "px");
          e.target.style.setProperty("--y", e.clientY - rect.top + "px");

          handleSubmit(e);
        }}
      >
        Begin Churn Prediction
      </button>
    </div>
  );
};

export default UploadSection;
